1	//! Echo model server: the full pegainfer serving stack (OpenAI-compatible
2	//! HTTP -> vLLM engine protocol -> the `Scheduler` contract) over an engine
3	//! that echoes the prompt back instead of running a model. No GPU, no
4	//! weights.
5	//!
6	//! It doubles as the reference for wiring a model line in: the echo line is
7	//! implemented in full below, and `main` at the bottom mirrors
8	//! `pegainfer-server/src/main.rs`'s serving flow with the compiled-in
9	//! registry reduced to the echo line alone.
10	//!
11	//! Run it (from the workspace root or anywhere else — the "model" is a
12	//! checked-in fixture next to this file):
13	//!
14	//!   cargo run -p pegainfer-frontend --example echo-server
15	//!
16	//! Talk to it:
17	//!
18	//!   curl http://127.0.0.1:8000/v1/completions \
19	//!     -H 'content-type: application/json' \
20	//!     -d '{"model": "echo", "prompt": "hello, pegainfer", "max_tokens": 64}'
21	//!
22	//!   # the completion text is the prompt back: "hello, pegainfer"
23	
24	use std::path::PathBuf;
25	
26	use anyhow::Context;
27	use anyhow::Result;
28	use clap::FromArgMatches;
29	use pegainfer_frontend::engine::Engine;
30	use pegainfer_frontend::engine::EngineInfo;
31	use pegainfer_frontend::engine::FinishReason;
32	use pegainfer_frontend::engine::LaunchedEngine;
33	use pegainfer_frontend::engine::QueuedRequest;
34	use pegainfer_frontend::engine::RequestId;
35	use pegainfer_frontend::engine::RequestLedger;
36	use pegainfer_frontend::engine::Scheduler;
37	use pegainfer_frontend::engine::SchedulerMetrics;
38	use pegainfer_frontend::engine::spawn_scheduler;
39	use pegainfer_frontend::model_line::LaunchContext;
40	use pegainfer_frontend::model_line::ModelLine;
41	use pegainfer_frontend::model_line::ModelLineRegistry;
42	use pegainfer_frontend::model_line::SharedArgs;
43	use pegainfer_frontend::model_line::provided_args;
44	use pegainfer_frontend::vllm;
45	
46	/// The echo "model" is checked in here: a `config.json` the echo line's
47	/// `probe` claims, plus a byte-level tokenizer for the serving stack.
48	const FIXTURE_MODEL_DIR: &str = concat!(env!("CARGO_MANIFEST_DIR"), "/examples/echo-model");
49	
50	// ---------------------------------------------------------------------------
51	// The echo model line, complete. A real model line lives in its own crate;
52	// everything it must implement against the frontend contract fits between
53	// here and `main`.
54	// ---------------------------------------------------------------------------
55	
56	/// The instance a server binary registers with its `ModelLineRegistry`.
57	static MODEL_LINE: EchoLine = EchoLine;
58	
59	/// Every new model line's checklist, minimal edition: claim a `config.json`
60	/// identity in `probe`, spawn schedulers in `launch`. No exclusive CLI flags
61	/// and no shared flags beyond the core ones.
62	struct EchoLine;
63	
64	impl ModelLine for EchoLine {
65	    fn name(&self) -> &'static str {
66	        "Echo"
67	    }
68	
69	    fn probe(&self, config: &serde_json::Value) -> Result<(), String> {
70	        let model_type = config.get("model_type").and_then(serde_json::Value::as_str);
71	        if model_type == Some("echo") {
72	            Ok(())
73	        } else {
74	            Err(format!("model_type {model_type:?} is not \"echo\""))
75	        }
76	    }
77	
78	    fn launch(&self, _ctx: &LaunchContext<'_>) -> Result<LaunchedEngine> {
79	        // A real line loads config/weights and may spawn several schedulers
80	        // (one per DP replica). The echo engine is one scheduler reporting no
81	        // KV pool and no servable-length limit of its own.
82	        Ok(Engine {
83	            schedulers: vec![spawn_scheduler("echo", EchoScheduler::default())],
84	            info: EngineInfo {
85	                kv_capacity: None,
86	                servable_len: None,
87	            },
88	            lora: None,
89	        }
90	        .into())
91	    }
92	}
93	
94	/// Answers each request with its own prompt tokens: echo
95	/// `prompt[..min(len, max_tokens)]` back, one token per step, then finish —
96	/// `FinishReason::Stop` for a full echo, `FinishReason::Length` when
97	/// `max_tokens` cut it short. One token per step keeps the per-token
98	/// streaming path warm instead of collapsing the response into one batch.
99	#[derive(Default)]
100	struct EchoScheduler {
101	    queued: Vec<QueuedRequest>,
102	    running: Vec<RunningRequest>,
103	}
104	
105	/// One admission onward: the request's ledger id plus its echo cursor —
106	/// prompt tokens not yet echoed and whether `max_tokens` trimmed the echo
107	/// short.
108	struct RunningRequest {
109	    id: RequestId,
110	    /// Prompt tokens not yet echoed, stored reversed for cheap pops.
111	    pending: Vec<u32>,
112	    /// Whether `max_tokens` trimmed the prompt (decides the finish reason).
113	    truncated: bool,
114	}
115	
116	impl Scheduler for EchoScheduler {
117	    fn submit(&mut self, request: QueuedRequest) {
118	        self.queued.push(request);
119	    }
120	
121	    fn step(&mut self, ledger: &mut RequestLedger) -> Result<()> {
122	        for QueuedRequest { id, request } in self.queued.drain(..) {
123	            if ledger.is_aborted(id) {
124	                ledger.retire(id);
125	                continue;
126	            }
127	            let echo_len = request.prompt_tokens.len().min(request.max_tokens);
128	            let truncated = echo_len < request.prompt_tokens.len();
129	            let mut pending = Vec::from(&request.prompt_tokens[..echo_len]);
130	            pending.reverse();
131	            ledger.admit(id);
132	            self.running.push(RunningRequest {
133	                id,
134	                pending,
135	                truncated,
136	            });
137	        }
138	        let mut still_running = Vec::new();
139	        for mut running in self.running.drain(..) {
140	            if ledger.is_aborted(running.id) {
141	                ledger.retire(running.id);
142	                continue;
143	            }
144	            if let Some(token) = running.pending.pop() {
145	                ledger.push_tokens(running.id, &[token], &[]);
146	                still_running.push(running);
147	            } else {
148	                let reason = if running.truncated {
149	                    FinishReason::Length
150	                } else {
151	                    FinishReason::Stop
152	                };
153	                ledger.finish(running.id, reason);
154	            }
155	        }
156	        self.running = still_running;
157	        Ok(())
158	    }
159	
160	    fn metrics(&self) -> SchedulerMetrics {
161	        SchedulerMetrics {
162	            num_running_reqs: self.running.len() as u64,
163	            num_waiting_reqs: self.queued.len() as u64,
164	            ..SchedulerMetrics::default()
165	        }
166	    }
167	}
168	
169	// ---------------------------------------------------------------------------
170	// Serving: same shape as pegainfer-server/src/main.rs — registry, detect by
171	// config.json, launch, serve — minus the lines echo doesn't need.
172	// ---------------------------------------------------------------------------
173	
174	#[tokio::main]
175	async fn main() -> Result<()> {
176	    let registry = ModelLineRegistry::new(vec![&MODEL_LINE]);
177	    let cmd = registry.build_command(
178	        clap::Command::new("echo-server").about("pegainfer echo model server (no GPU, no weights)"),
179	    );
180	    let matches = cmd.clone().get_matches();
181	    let mut shared = SharedArgs::from_arg_matches(&matches)
182	        .map_err(|error| anyhow::anyhow!("invalid CLI args: {error}"))?;
183	
184	    // Default to the checked-in fixture; --model-path still works if you keep
185	    // your own copy of these few files somewhere else.
186	    let provided = provided_args(&matches, &cmd);
187	    if !provided.contains("model_path") {
188	        shared.model_path = PathBuf::from(FIXTURE_MODEL_DIR);
189	    }
190	
191	    let config_path = shared.model_path.join("config.json");
192	    let content = std::fs::read_to_string(&config_path)
193	        .with_context(|| format!("failed to read {}", config_path.display()))?;
194	    let config: serde_json::Value = serde_json::from_str(&content)
195	        .with_context(|| format!("failed to parse {}", config_path.display()))?;
196	
197	    let line = registry.detect(&config)?;
198	    registry.validate_provided(line, &provided, &cmd)?;
199	    shared.validate(&provided)?;
200	
201	    let ctx = LaunchContext {
202	        model_path: &shared.model_path,
203	        config: &config,
204	        shared: &shared,
205	        matches: &matches,
206	    };
207	    let plan = line.serve_plan(&ctx)?;
208	    // Echo has nothing to load; a real line hides a blocking weights load
209	    // behind this call (see pegainfer-server's spawn_blocking).
210	    let engine = line.launch(&ctx)?;
211	
212	    let served_model_name = vec![
213	        shared
214	            .served_model_name
215	            .clone()
216	            .unwrap_or_else(|| "echo".to_owned()),
217	    ];
218	    eprintln!(
219	        "serving the echo model on port {} (model={:?}); Ctrl-C to stop",
220	        shared.port, served_model_name[0],
221	    );
222	    vllm::serve_with_engine_count(
223	        std::future::ready(Ok(engine)),
224	        &shared.model_path,
225	        served_model_name,
226	        vllm::ParserSelection::Auto,
227	        shared.port,
228	        None,
229	        plan.scheduler_partition_count,
230	        vllm::shutdown_token_from_ctrl_c(),
231	    )
232	    .await
233	}
